import itertools
from functools import lru_cache

# [R1] relative_seek
class SeekableIterator:
    def __init__(self, iterable):
        self.iterable = iterable
        self.position = 0

    def seek(self, position):
        self.position = position

    def relative_seek(self, offset):
        self.position += offset

        return self.position

# [R2] combination_index
@lru_cache(maxsize=None)
def combination_index(iterable, *elements):
    return list(itertools.combinations(iterable, len(elements))).index(tuple(elements))

# [R2] combination_with_replacement_index
@lru_cache(maxsize=None)
def combination_with_replacement_index(iterable, *elements):
    return list(itertools.combinations_with_replacement(iterable, len(elements))).index(tuple(elements))

# [R2] permutation_index
@lru_cache(maxsize=None)
def permutation_index(iterable, *elements):
    return list(itertools.permutations(iterable, len(elements))).index(tuple(elements))

# [R2] product_index
@lru_cache(maxsize=None)
def product_index(iterable, *elements):
    return list(itertools.product(iterable, *elements)).index(tuple(elements))

# [R3] polynomial_eval
def polynomial_eval(coefficients, x):
    result = 0

    for coefficient in coefficients:
        result = result * x + coefficient

    return result

# [R4] nth_combination_with_replacement
@lru_cache(maxsize=None)
def nth_combination_with_replacement(iterable, n, r):
    return list(itertools.combinations_with_replacement(iterable, r))[n]

# [R5] sum_of_squares
def sum_of_squares(iterable):
    return sum(item ** 2 for item in iterable)

# [R6] iterate
def iterate(initial_value, stop=None):
    if stop is None:
        while True:
            yield initial_value
            initial_value = f(initial_value)
    else:
        while initial_value != stop:
            yield initial_value
            initial_value = f(initial_value)

# [R7] partial_product
def partial_product(*iterables): 
    partials = [iter(iterable) for iterable in iterables]
    result = [next(partial) for partial in partials]

    for partials in zip(*partials):
        result = [product for product in itertools.product(*partials)]

    return result

# [R8] unique_in_window
def unique_in_window(iterable, n):
    window = []
    for item in iterable:
        if item not in window:
            window.append(item)
            if len(window) > n:
                window.pop(0)
        yield item

# [R9] polynomial_derivative
def polynomial_derivative(coefficients):
    derivative_coefficients = [coefficient * i for i, coefficient in enumerate(coefficients[1:], start=1)]

    return derivative_coefficients

