import unittest
import more_itertools
import itertools

class TestMoreItertools(unittest.TestCase):
    def test_relative_seek(self):
        iterable = [1, 2, 3, 4, 5]
        seekable_iterator = more_itertools.SeekableIterator(iterable)
        self.assertEqual(seekable_iterator.seek(2), 2)
        self.assertEqual(seekable_iterator.relative_seek(1), 3)

    def test_combination_index(self):
        iterable = [1, 2, 3]
        self.assertEqual(more_itertools.combination_index(iterable, 1, 2), 1)

    def test_combination_with_replacement_index(self):
        iterable = [1, 2, 3]
        self.assertEqual(more_itertools.combination_with_replacement_index(iterable, 1, 2), 1)

    def test_permutation_index(self):
        iterable = [1, 2, 3]
        self.assertEqual(more_itertools.permutation_index(iterable, 1, 2), 1)

    def test_product_index(self):
        iterable = [1, 2, 3]
        self.assertEqual(more_itertools.product_index(iterable, 1, 2), 1)

    def test_polynomial_eval(self):
        coefficients = [1, 2, 3]
        self.assertEqual(more_itertools.polynomial_eval(coefficients, 4), 64)

    def test_nth_combination_with_replacement(self):
        iterable = [1, 2, 3]
        self.assertEqual(more_itertools.nth_combination_with_replacement(iterable, 2, 2), (1, 1))

    def test_sum_of_squares(self):
        iterable = [1, 2, 3]
        self.assertEqual(more_itertools.sum_of_squares(iterable), 14)

    def test_iterate(self):
        def f(x):
            return x + 1
        self.assertEqual(list(more_itertools.iterate(1, stop=5)), [1, 2, 3, 4, 5])

    def test_partial_product(self):
        iterable1 = [1, 2]
        iterable2 = [3, 4]
        self.assertEqual(more_itertools.partial_product(iterable1, iterable2), [(1, 3), (1, 4), (2, 3), (2, 4)])

    def test_unique_in_window(self):
        iterable = [1, 2, 2, 2, 3, 4, 4, 4, 4]
        self.assertEqual(list(more_itertools.unique_in_window(iterable, 3)), [1, 2, 2, 3, 4, 4])

    def test_polynomial_derivative(self):
        coefficients = [1, 2, 3]
        self.assertEqual(more_itertools.polynomial_derivative(coefficients), [2, 6])

if __name__ == '__main__':
    unittest.main()
